                        {
                            this.clear(); 
                        }
                    },
                    onChange: function(value) {
                        if(value.toLowerCase() == 'đặt hàng' || value.toLowerCase() == 'order')
                        {
                            $('#productsl')[0].selectize.clear();
                            $('#productsl').parent().removeClass('success');
                            $('#productsl').parent().addClass('hideexport');
                        }
