                        {
                            $('#productsl').parent().removeClass('hideexport');
                        }
                    }
                });
                $product = $('#productsl').selectize({
                    onDropdownOpen:  function(value)
                    {
                        var s = this;
                        $.each(this.options, function (e) {
                            if($(this)[0].disabled)
                            {
                                s.removeOption($(this)[0].text);
                            }
                        });
