                        if((demand.toLowerCase() == 'đặt hàng' || demand.toLowerCase() == 'order') &&(value.toLowerCase() == 'g kitchen' || value.toLowerCase() == 'mamachoice' || value.toLowerCase() == 'wyn'))
                        {
